Method.Source:
    /// <summary>
    /// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
    /// find method to select <c>METCBCTDeptAllocTable</c> record
    /// </summary>
    /// <param name = "_vendAccount">vendor account</param>
    /// <param name = "_serviceItemId">service item id</param>
    /// <param name = "_forUpdate">select for updating, boolean true or false</param>
    /// <returns>record of type <c>METCBCTDeptAllocTable</c> if found</returns>
    static METCBCTDeptAllocTable find(VendAccount _vendAccount, ItemId _serviceItemId, boolean _forUpdate = false)
    {
        METCBCTDeptAllocTable metCBCTDeptAllocTable;

        if (_vendAccount && _serviceItemId)
        {
            metCBCTDeptAllocTable.selectForUpdate(_forUpdate);
            
            select firstonly metCBCTDeptAllocTable
                where metCBCTDeptAllocTable.VendAccount     == _vendAccount &&
                      metCBCTDeptAllocTable.ServiceItemId   == _serviceItemId;
        }

        return metCBCTDeptAllocTable;
    }

    /// <summary>
    /// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
    /// find method to select <c>METCBCTDeptAllocTable</c> record belongs to specific vendor
    /// </summary>
    /// <param name = "_vendAccount">vendor account</param>      
    /// <returns>record of type <c>METCBCTDeptAllocTable</c> if found</returns>
    static METCBCTDeptAllocTable findVendor(VendAccount _vendAccount)
    {
        METCBCTDeptAllocTable metCBCTDeptAllocTable;

        if (_vendAccount)
        {         
            select firstonly metCBCTDeptAllocTable
                where metCBCTDeptAllocTable.VendAccount     == _vendAccount;
        }

        return metCBCTDeptAllocTable;
    }

    /// <summary>
    /// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
    /// get total allocation percentagefor a specific vendor
    /// </summary>
    /// <param name = "_vendAccount">vendor account</param>
    
    static Percent getTotalAllocPctperVendor(VendAccount _vendAccount)
    {
        METCBCTDeptAllocTable metCBCTDeptAllocTable;

        if (_vendAccount)
        {
            select sum(AllocationPct) from metCBCTDeptAllocTable
                where metCBCTDeptAllocTable.VendAccount == _vendAccount;
        }

        return metCBCTDeptAllocTable.AllocationPct;
    }
